{
  "name": "GirviGold - Gold Loan Ledger",
  "description": "A comprehensive digital ledger for managing gold and silver loans (Girvi). Features automated serial numbering, detailed item tracking, monthly interest calculation (3% Gold, 4% Silver), robust search capabilities, and analytical dashboards."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type MetalType = 'Gold' | 'Silver' | 'Both';

export interface LoanEntry {
  id: string;
  serialNumber: number;
  date: string;
  name: string;
  guardian: string;
  address: string;
  contactNumber: string;
  metalType: MetalType;
  description: string;
  weight: number;
  amount: number;
  interestRate: number;
  status: 'Active' | 'Closed';
}

export interface Statistics {
  totalPrincipal: number;
  totalInterestMonthly: number;
  activeLoansCount: number;
  goldLoansCount: number;
  silverLoansCount: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  PlusCircle, 
  BookOpen, 
  Search, 
  TrendingUp,
  Settings,
  Menu,
  X
} from 'lucide-react';
import { LoanEntry } from './types';
import Dashboard from './components/Dashboard';
import LoanEntryForm from './components/LoanEntryForm';
import Ledger from './components/Ledger';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'entry' | 'ledger'>('dashboard');
  const [loans, setLoans] = useState<LoanEntry[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Load data from LocalStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('girvi_loans');
    if (saved) {
      try {
        setLoans(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved loans", e);
      }
    }
  }, []);

  // Save data to LocalStorage on change
  useEffect(() => {
    localStorage.setItem('girvi_loans', JSON.stringify(loans));
  }, [loans]);

  const addLoan = (newLoan: Omit<LoanEntry, 'id' | 'serialNumber' | 'status'>) => {
    const nextSerial = loans.length > 0 ? Math.max(...loans.map(l => l.serialNumber)) + 1 : 1;
    const loan: LoanEntry = {
      ...newLoan,
      id: crypto.randomUUID(),
      serialNumber: nextSerial,
      status: 'Active'
    };
    setLoans([...loans, loan]);
    setActiveTab('ledger');
  };

  const deleteLoan = (id: string) => {
    if (window.confirm("Are you sure you want to delete this record?")) {
      setLoans(loans.filter(l => l.id !== id));
    }
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const NavItem = ({ id, icon: Icon, label }: { id: typeof activeTab, icon: any, label: string }) => (
    <button
      onClick={() => {
        setActiveTab(id);
        setIsSidebarOpen(false);
      }}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
        activeTab === id 
          ? 'bg-yellow-500 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-yellow-50 hover:text-yellow-600'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium">{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Mobile Header */}
      <div className="md:hidden bg-white border-b border-slate-200 px-4 py-3 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center space-x-2">
          <div className="bg-yellow-500 p-2 rounded-lg text-white">
            <TrendingUp size={24} />
          </div>
          <span className="text-xl font-bold text-slate-800">GirviGold</span>
        </div>
        <button onClick={toggleSidebar} className="text-slate-600">
          {isSidebarOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Sidebar (Desktop & Mobile Overlay) */}
      <aside className={`
        fixed inset-y-0 left-0 z-40 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 ease-in-out md:relative md:translate-x-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:flex items-center space-x-3 mb-10 px-2">
            <div className="bg-yellow-500 p-2 rounded-xl text-white shadow-md">
              <TrendingUp size={24} />
            </div>
            <span className="text-2xl font-bold text-slate-800 tracking-tight">GirviGold</span>
          </div>

          <nav className="space-y-2 flex-grow">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="entry" icon={PlusCircle} label="New Loan Entry" />
            <NavItem id="ledger" icon={BookOpen} label="Loan Ledger" />
          </nav>

          <div className="pt-6 border-t border-slate-100">
            <button className="w-full flex items-center space-x-3 px-4 py-3 text-slate-400 hover:text-slate-600 transition-colors">
              <Settings size={20} />
              <span className="font-medium">Settings</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
          {activeTab === 'dashboard' && <Dashboard loans={loans} />}
          {activeTab === 'entry' && <LoanEntryForm onAdd={addLoan} nextSerial={loans.length > 0 ? Math.max(...loans.map(l => l.serialNumber)) + 1 : 1} />}
          {activeTab === 'ledger' && <Ledger loans={loans} onDelete={deleteLoan} />}
        </div>
      </main>

      {/* Mobile Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-30 md:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie
} from 'recharts';
import { IndianRupee, Users, Scale, AlertCircle } from 'lucide-react';
import { LoanEntry } from '../types';

interface DashboardProps {
  loans: LoanEntry[];
}

const Dashboard: React.FC<DashboardProps> = ({ loans }) => {
  const stats = useMemo(() => {
    const totalPrincipal = loans.reduce((acc, curr) => acc + curr.amount, 0);
    const activeLoansCount = loans.filter(l => l.status === 'Active').length;
    const totalInterestMonthly = loans.reduce((acc, curr) => acc + (curr.amount * curr.interestRate / 100), 0);

    const metalCounts = {
      Gold: loans.filter(l => l.metalType === 'Gold').length,
      Silver: loans.filter(l => l.metalType === 'Silver').length,
      Both: loans.filter(l => l.metalType === 'Both').length,
    };

    return { totalPrincipal, activeLoansCount, totalInterestMonthly, metalCounts };
  }, [loans]);

  const pieData = [
    { name: 'Gold', value: stats.metalCounts.Gold, color: '#EAB308' },
    { name: 'Silver', value: stats.metalCounts.Silver, color: '#94A3B8' },
    { name: 'Both', value: stats.metalCounts.Both, color: '#FACC15' },
  ];

  const recentTrends = useMemo(() => {
    // Group by month for simple trend
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const currentYear = new Date().getFullYear();

    return months.map((month, index) => {
      const monthLoans = loans.filter(l => {
        const d = new Date(l.date);
        return d.getMonth() === index && d.getFullYear() === currentYear;
      });
      return {
        name: month,
        amount: monthLoans.reduce((sum, l) => sum + l.amount, 0)
      };
    });
  }, [loans]);

  const StatCard = ({ label, value, icon: Icon, colorClass }: any) => (
    <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-start justify-between">
      <div>
        <p className="text-slate-500 text-sm font-medium mb-1">{label}</p>
        <h3 className="text-2xl font-bold text-slate-800">{value}</h3>
      </div>
      <div className={`p-3 rounded-xl ${colorClass}`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header>
        <h1 className="text-3xl font-bold text-slate-800">Business Overview</h1>
        <p className="text-slate-500">Real-time tracking of your gold loan portfolio</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          label="Total Principal Out" 
          value={`₹${stats.totalPrincipal.toLocaleString()}`} 
          icon={IndianRupee} 
          colorClass="bg-yellow-50 text-yellow-600" 
        />
        <StatCard 
          label="Est. Monthly Interest" 
          value={`₹${stats.totalInterestMonthly.toLocaleString()}`} 
          icon={TrendingUp} 
          colorClass="bg-green-50 text-green-600" 
        />
        <StatCard 
          label="Active Loans" 
          value={stats.activeLoansCount} 
          icon={Users} 
          colorClass="bg-blue-50 text-blue-600" 
        />
        <StatCard 
          label="Total Items Weight" 
          value={`${loans.reduce((acc, curr) => acc + curr.weight, 0).toFixed(2)}g`} 
          icon={Scale} 
          colorClass="bg-purple-50 text-purple-600" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Loan Trend Chart */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Disbursement Trend ({new Date().getFullYear()})</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={recentTrends}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="amount" fill="#EAB308" radius={[4, 4, 0, 0]} barSize={32} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Metal Distribution Chart */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Asset Distribution</h3>
          <div className="h-[300px] flex items-center justify-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="space-y-3 pr-8">
              {pieData.map((item) => (
                <div key={item.name} className="flex items-center space-x-2">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
                  <span className="text-sm font-medium text-slate-600">{item.name}: {item.value}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {loans.length === 0 && (
        <div className="bg-yellow-50 border border-yellow-100 p-8 rounded-2xl flex flex-col items-center text-center">
          <AlertCircle size={48} className="text-yellow-400 mb-4" />
          <h3 className="text-lg font-bold text-yellow-800">No Data Available</h3>
          <p className="text-yellow-700 max-w-md">Start by adding a new loan entry to see your dashboard come to life with analytics.</p>
        </div>
      )}
    </div>
  );
};

const TrendingUp = ({ size }: { size: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <polyline points="23 6 13.5 15.5 8.5 10.5 1 18" /><polyline points="17 6 23 6 23 12" />
  </svg>
);

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Save, User, MapPin, Phone, Scale, Info, IndianRupee } from 'lucide-react';
import { LoanEntry, MetalType } from '../types';

interface LoanEntryFormProps {
  onAdd: (loan: Omit<LoanEntry, 'id' | 'serialNumber' | 'status'>) => void;
  nextSerial: number;
}

const LoanEntryForm: React.FC<LoanEntryFormProps> = ({ onAdd, nextSerial }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    name: '',
    guardian: '',
    address: '',
    contactNumber: '',
    metalType: 'Gold' as MetalType,
    description: '',
    weight: '' as string | number,
    amount: '' as string | number,
  });

  // Default interest rates
  const getInterestRate = (metal: MetalType) => {
    if (metal === 'Gold') return 3;
    if (metal === 'Silver') return 4;
    return 3.5; // Average/Default for "Both"
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd({
      ...formData,
      weight: Number(formData.weight),
      amount: Number(formData.amount),
      interestRate: getInterestRate(formData.metalType)
    });
    // Form is reset via unmount in parent or state reset here if needed
  };

  const inputClass = "w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-yellow-500 focus:border-yellow-500 transition-all outline-none";
  const labelClass = "block text-sm font-semibold text-slate-700 mb-2 ml-1";

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500">
      <header className="mb-8">
        <h1 className="text-3xl font-bold text-slate-800">New Loan Entry</h1>
        <p className="text-slate-500">Record a new collateral-based loan into the ledger</p>
      </header>

      <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-8 space-y-8">
          {/* Header Info */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pb-6 border-b border-slate-100">
            <div>
              <label className={labelClass}>Serial Number (Auto)</label>
              <div className="px-4 py-2.5 bg-slate-100 border border-slate-200 rounded-xl text-slate-500 font-mono">
                #{String(nextSerial).padStart(4, '0')}
              </div>
            </div>
            <div>
              <label className={labelClass}>Entry Date</label>
              <input 
                type="date" 
                className={inputClass}
                value={formData.date}
                onChange={e => setFormData({...formData, date: e.target.value})}
                required
              />
            </div>
          </div>

          {/* Customer Section */}
          <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center space-x-2">
              <User size={20} className="text-yellow-500" />
              <span>Customer Information</span>
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelClass}>Customer Full Name</label>
                <input 
                  type="text" 
                  className={inputClass}
                  placeholder="e.g. Rahul Sharma"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  required
                />
              </div>
              <div>
                <label className={labelClass}>Guardian/Father's Name</label>
                <input 
                  type="text" 
                  className={inputClass}
                  placeholder="e.g. S/o Mr. Vijay Sharma"
                  value={formData.guardian}
                  onChange={e => setFormData({...formData, guardian: e.target.value})}
                  required
                />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelClass}>Contact Number</label>
                <div className="relative">
                  <Phone className="absolute left-4 top-3 text-slate-400" size={18} />
                  <input 
                    type="tel" 
                    className={`${inputClass} pl-11`}
                    placeholder="10-digit mobile"
                    value={formData.contactNumber}
                    onChange={e => setFormData({...formData, contactNumber: e.target.value})}
                    required
                  />
                </div>
              </div>
              <div>
                <label className={labelClass}>Full Address</label>
                <div className="relative">
                  <MapPin className="absolute left-4 top-3 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    className={`${inputClass} pl-11`}
                    placeholder="Street, City, Pin Code"
                    value={formData.address}
                    onChange={e => setFormData({...formData, address: e.target.value})}
                    required
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Item Section */}
          <div className="space-y-6 pt-6 border-t border-slate-100">
            <h3 className="text-lg font-bold text-slate-800 flex items-center space-x-2">
              <Scale size={20} className="text-yellow-500" />
              <span>Metal & Asset Details</span>
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className={labelClass}>Metal Category</label>
                <select 
                  className={inputClass}
                  value={formData.metalType}
                  onChange={e => setFormData({...formData, metalType: e.target.value as MetalType})}
                >
                  <option value="Gold">Gold (Girvi - 3% Interest)</option>
                  <option value="Silver">Silver (Girvi - 4% Interest)</option>
                  <option value="Both">Both (3.5% Interest)</option>
                </select>
              </div>
              <div className="md:col-span-2">
                <label className={labelClass}>Metal Description</label>
                <div className="relative">
                  <Info className="absolute left-4 top-3 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    className={`${inputClass} pl-11`}
                    placeholder="e.g. 2 Gold Bangles, 1 Pair Silver Anklets"
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                    required
                  />
                </div>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className={labelClass}>Total Weight (in grams)</label>
                <input 
                  type="number" 
                  step="0.001"
                  className={inputClass}
                  placeholder="0.000"
                  value={formData.weight}
                  onChange={e => setFormData({...formData, weight: e.target.value})}
                  required
                />
              </div>
              <div>
                <label className={labelClass}>Loan Amount (Principal)</label>
                <div className="relative">
                  <span className="absolute left-4 top-2.5 text-slate-500 font-bold">₹</span>
                  <input 
                    type="number" 
                    className={`${inputClass} pl-8 font-bold text-lg`}
                    placeholder="0"
                    value={formData.amount}
                    onChange={e => setFormData({...formData, amount: e.target.value})}
                    required
                  />
                </div>
              </div>
              <div>
                <label className={labelClass}>Interest Rate (% Monthly)</label>
                <div className="px-4 py-2.5 bg-yellow-50 border border-yellow-200 rounded-xl text-yellow-700 font-bold">
                  {getInterestRate(formData.metalType)}% p.m.
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-slate-50 p-6 flex justify-end">
          <button 
            type="submit"
            className="bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-3 px-8 rounded-xl shadow-lg shadow-yellow-200 transition-all flex items-center space-x-2"
          >
            <Save size={20} />
            <span>Save Entry to Ledger</span>
          </button>
        </div>
      </form>
    </div>
  );
};

export default LoanEntryForm;

export type MetalType = 'Gold' | 'Silver' | 'Both';

export interface LoanEntry {
  id: string;
  serialNumber: number;
  date: string;
  name: string;
  guardian: string;
  address: string;
  contactNumber: string;
  metalType: MetalType;
  description: string;
  weight: number;
  netWeight: number;
  remark: string;
  amount: number;
  interestRate: number;
  status: 'Active' | 'Closed';
}

export interface Statistics {
  totalPrincipal: number;
  totalInterestMonthly: number;
  activeLoansCount: number;
  goldLoansCount: number;
  silverLoansCount: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  PlusCircle, 
  BookOpen, 
  TrendingUp,
  Settings,
  Menu,
  X
} from 'lucide-react';
import { LoanEntry } from './types';
import Dashboard from './components/Dashboard';
import LoanEntryForm from './components/LoanEntryForm';
import Ledger from './components/Ledger';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'entry' | 'ledger'>('dashboard');
  const [loans, setLoans] = useState<LoanEntry[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [editingLoan, setEditingLoan] = useState<LoanEntry | null>(null);

  // Load data from LocalStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('girvi_loans');
    if (saved) {
      try {
        setLoans(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved loans", e);
      }
    }
  }, []);

  // Save data to LocalStorage on change
  useEffect(() => {
    localStorage.setItem('girvi_loans', JSON.stringify(loans));
  }, [loans]);

  const saveLoan = (loanData: Omit<LoanEntry, 'id' | 'status'>) => {
    if (editingLoan) {
      setLoans(loans.map(l => l.id === editingLoan.id ? { ...loanData, id: editingLoan.id, status: editingLoan.status } : l));
      setEditingLoan(null);
    } else {
      const loan: LoanEntry = {
        ...loanData,
        id: crypto.randomUUID(),
        status: 'Active'
      };
      setLoans([...loans, loan]);
    }
    setActiveTab('ledger');
  };

  const deleteLoan = (id: string) => {
    if (window.confirm("Are you sure you want to delete this record?")) {
      setLoans(loans.filter(l => l.id !== id));
    }
  };

  const handleEdit = (loan: LoanEntry) => {
    setEditingLoan(loan);
    setActiveTab('entry');
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const NavItem = ({ id, icon: Icon, label }: { id: typeof activeTab, icon: any, label: string }) => (
    <button
      onClick={() => {
        setActiveTab(id);
        if (id !== 'entry') setEditingLoan(null);
        setIsSidebarOpen(false);
      }}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
        activeTab === id 
          ? 'bg-yellow-500 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-yellow-50 hover:text-yellow-600'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium">{label}</span>
    </button>
  );

  const nextAutoSerial = loans.length > 0 ? Math.max(...loans.map(l => l.serialNumber)) + 1 : 1;

  return (
