import React, { useState, useEffect } from 'react';
import { Save, User, MapPin, Phone, Scale, Info, MessageSquare, X } from 'lucide-react';
import { LoanEntry, MetalType } from '../types';

interface LoanEntryFormProps {
  onSave: (loan: Omit<LoanEntry, 'id' | 'status'>) => void;
  nextSerial: number;
  editingLoan: LoanEntry | null;
  onCancel?: () => void;
}

const LoanEntryForm: React.FC<LoanEntryFormProps> = ({ onSave, nextSerial, editingLoan, onCancel }) => {
  const [formData, setFormData] = useState({
    serialNumber: String(nextSerial),
    date: new Date().toISOString().split('T')[0],
    name: '',
    guardian: '',
    address: '',
    contactNumber: '',
    metalType: 'Gold' as MetalType,
    description: '',
    weight: '' as string | number,
    netWeight: '' as string | number,
    remark: '',
    amount: '' as string | number,
  });

  // Load editing data if present
  useEffect(() => {
    if (editingLoan) {
      setFormData({
        serialNumber: String(editingLoan.serialNumber),
        date: editingLoan.date,
        name: editingLoan.name,
        guardian: editingLoan.guardian,
        address: editingLoan.address,
        contactNumber: editingLoan.contactNumber,
        metalType: editingLoan.metalType,
        description: editingLoan.description,
        weight: editingLoan.weight,
        netWeight: editingLoan.netWeight,
        remark: editingLoan.remark,
        amount: editingLoan.amount,
      });
    } else {
      setFormData(prev => ({ ...prev, serialNumber: String(nextSerial) }));
    }
  }, [editingLoan, nextSerial]);

  // Default interest rates
  const getInterestRate = (metal: MetalType) => {
    if (metal === 'Gold') return 3;
    if (metal === 'Silver') return 4;
    return 3.5;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      serialNumber: Number(formData.serialNumber),
      weight: Number(formData.weight),
      netWeight: Number(formData.netWeight),
      amount: Number(formData.amount),
      interestRate: getInterestRate(formData.metalType)
    });
  };

  const inputClass = "w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-yellow-500 focus:border-yellow-500 transition-all outline-none";
  const labelClass = "block text-sm font-semibold text-slate-700 mb-2 ml-1";

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500">
      <header className="mb-8 flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">{editingLoan ? 'Edit Loan Entry' : 'New Loan Entry'}</h1>
          <p className="text-slate-500">Record a new collateral-based loan into the ledger</p>
        </div>
        {editingLoan && (
          <button 
            onClick={onCancel}
            className="flex items-center space-x-2 text-slate-500 hover:text-slate-800 transition-colors bg-white px-4 py-2 rounded-lg border border-slate-200"
          >
            <X size={18} />
            <span>Cancel Edit</span>
          </button>
        )}
      </header>

      <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-8 space-y-8">
          {/* Header Info */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pb-6 border-b border-slate-100">
            <div>
              <label className={labelClass}>Serial Number (Auto/Manual)</label>
              <input 
                type="number"
                className={`${inputClass} font-mono`}
                value={formData.serialNumber}
                onChange={e => setFormData({...formData, serialNumber: e.target.value})}
                required
              />
            </div>
            <div>
              <label className={labelClass}>Entry Date</label>
              <input 
                type="date" 
                className={inputClass}
                value={formData.date}
                onChange={e => setFormData({...formData, date: e.target.value})}
                required
              />
            </div>
          </div>

          {/* Customer Section */}
          <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center space-x-2">
              <User size={20} className="text-yellow-500" />
              <span>Customer Information</span>
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelClass}>Customer Full Name</label>
                <input 
                  type="text" 
                  className={inputClass}
                  placeholder="e.g. Rahul Sharma"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  required
                />
              </div>
              <div>
                <label className={labelClass}>Guardian/Father's Name</label>
                <input 
                  type="text" 
                  className={inputClass}
                  placeholder="e.g. S/o Mr. Vijay Sharma"
                  value={formData.guardian}
                  onChange={e => setFormData({...formData, guardian: e.target.value})}
                  required
                />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelClass}>Contact Number</label>
                <div className="relative">
                  <Phone className="absolute left-4 top-3 text-slate-400" size={18} />
                  <input 
                    type="tel" 
                    className={`${inputClass} pl-11`}
                    placeholder="10-digit mobile"
                    value={formData.contactNumber}
                    onChange={e => setFormData({...formData, contactNumber: e.target.value})}
                    required
                  />
                </div>
              </div>
              <div>
                <label className={labelClass}>Full Address</label>
                <div className="relative">
                  <MapPin className="absolute left-4 top-3 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    className={`${inputClass} pl-11`}
                    placeholder="Street, City, Pin Code"
                    value={formData.address}
                    onChange={e => setFormData({...formData, address: e.target.value})}
                    required
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Item Section */}
          <div className="space-y-6 pt-6 border-t border-slate-100">
            <h3 className="text-lg font-bold text-slate-800 flex items-center space-x-2">
              <Scale size={20} className="text-yellow-500" />
              <span>Metal & Asset Details</span>
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className={labelClass}>Metal Category</label>
                <select 
                  className={inputClass}
                  value={formData.metalType}
                  onChange={e => setFormData({...formData, metalType: e.target.value as MetalType})}
                >
                  <option value="Gold">Gold (Girvi - 3%)</option>
                  <option value="Silver">Silver (Girvi - 4%)</option>
                  <option value="Both">Both (3.5%)</option>
                </select>
              </div>
              <div className="md:col-span-2">
                <label className={labelClass}>Metal Description</label>
                <div className="relative">
                  <Info className="absolute left-4 top-3 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    className={`${inputClass} pl-11`}
                    placeholder="e.g. 2 Gold Bangles"
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                    required
                  />
                </div>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div>
                <label className={labelClass}>Gross Weight (g)</label>
                <input 
                  type="number" 
                  step="0.001"
                  className={inputClass}
                  placeholder="0.000"
                  value={formData.weight}
                  onChange={e => setFormData({...formData, weight: e.target.value})}
                  required
                />
              </div>
              <div>
                <label className={labelClass}>Net Weight (g)</label>
                <input 
                  type="number" 
                  step="0.001"
                  className={inputClass}
                  placeholder="0.000"
                  value={formData.netWeight}
                  onChange={e => setFormData({...formData, netWeight: e.target.value})}
                  required
                />
              </div>
              <div>
                <label className={labelClass}>Loan Amount</label>
                <div className="relative">
                  <span className="absolute left-4 top-2.5 text-slate-500 font-bold">₹</span>
                  <input 
                    type="number" 
                    className={`${inputClass} pl-8 font-bold text-lg`}
                    placeholder="0"
                    value={formData.amount}
                    onChange={e => setFormData({...formData, amount: e.target.value})}
                    required
                  />
                </div>
              </div>
              <div>
                <label className={labelClass}>Interest Rate</label>
                <div className="px-4 py-2.5 bg-yellow-50 border border-yellow-200 rounded-xl text-yellow-700 font-bold text-center">
                  {getInterestRate(formData.metalType)}% p.m.
                </div>
              </div>
            </div>
            <div>
              <label className={labelClass}>Remark / Internal Notes</label>
              <div className="relative">
                <MessageSquare className="absolute left-4 top-3 text-slate-400" size={18} />
                <textarea 
                  className={`${inputClass} pl-11 min-h-[100px]`}
                  placeholder="Any specific condition or identification mark..."
                  value={formData.remark}
                  onChange={e => setFormData({...formData, remark: e.target.value})}
                />
              </div>
            </div>
          </div>
        </div>

        <div className="bg-slate-50 p-6 flex justify-end">
          <button 
            type="submit"
            className="bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-3 px-8 rounded-xl shadow-lg shadow-yellow-200 transition-all flex items-center space-x-2"
          >
            <Save size={20} />
            <span>{editingLoan ? 'Update Ledger Entry' : 'Save Entry to Ledger'}</span>
          </button>
        </div>
      </form>
    </div>
  );
};

