import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  PlusCircle, 
  BookOpen, 
  TrendingUp,
  Settings,
  Menu,
  X,
  Users
} from 'lucide-react';
import { LoanEntry } from './types';
import Dashboard from './components/Dashboard';
import LoanEntryForm from './components/LoanEntryForm';
import Ledger from './components/Ledger';
import CustomerSheet from './components/CustomerSheet';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'entry' | 'ledger' | 'customers'>('dashboard');
  const [loans, setLoans] = useState<LoanEntry[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [editingLoan, setEditingLoan] = useState<LoanEntry | null>(null);

  // Load data from LocalStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('girvi_loans');
    if (saved) {
      try {
        setLoans(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved loans", e);
      }
    }
  }, []);

  // Save data to LocalStorage on change
  useEffect(() => {
    localStorage.setItem('girvi_loans', JSON.stringify(loans));
  }, [loans]);

  const saveLoan = (loanData: Omit<LoanEntry, 'id' | 'status'>) => {
    if (editingLoan) {
      setLoans(loans.map(l => l.id === editingLoan.id ? { ...loanData, id: editingLoan.id, status: editingLoan.status } : l));
      setEditingLoan(null);
    } else {
      const loan: LoanEntry = {
        ...loanData,
        id: crypto.randomUUID(),
        status: 'Active'
      };
      setLoans([...loans, loan]);
    }
    setActiveTab('ledger');
  };

  const deleteLoan = (id: string) => {
    if (window.confirm("Are you sure you want to delete this record?")) {
      setLoans(loans.filter(l => l.id !== id));
    }
  };

  const handleEdit = (loan: LoanEntry) => {
    setEditingLoan(loan);
    setActiveTab('entry');
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const NavItem = ({ id, icon: Icon, label }: { id: typeof activeTab, icon: any, label: string }) => (
    <button
      onClick={() => {
        setActiveTab(id);
        if (id !== 'entry') setEditingLoan(null);
        setIsSidebarOpen(false);
      }}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
        activeTab === id 
          ? 'bg-yellow-500 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-yellow-50 hover:text-yellow-600'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium">{label}</span>
    </button>
  );

  const nextAutoSerial = loans.length > 0 ? Math.max(...loans.map(l => l.serialNumber)) + 1 : 1;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Mobile Header */}
      <div className="md:hidden bg-white border-b border-slate-200 px-4 py-3 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center space-x-2">
          <div className="bg-yellow-500 p-2 rounded-lg text-white">
            <TrendingUp size={24} />
          </div>
          <span className="text-xl font-bold text-slate-800">GirviGold</span>
        </div>
        <button onClick={toggleSidebar} className="text-slate-600">
          {isSidebarOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-40 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 ease-in-out md:relative md:translate-x-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:flex items-center space-x-3 mb-10 px-2">
            <div className="bg-yellow-500 p-2 rounded-xl text-white shadow-md">
              <TrendingUp size={24} />
            </div>
            <span className="text-2xl font-bold text-slate-800 tracking-tight">GirviGold</span>
          </div>

          <nav className="space-y-2 flex-grow">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="entry" icon={PlusCircle} label={editingLoan ? "Edit Loan Entry" : "New Loan Entry"} />
            <NavItem id="ledger" icon={BookOpen} label="Loan Ledger" />
            <NavItem id="customers" icon={Users} label="Customer Sheet" />
          </nav>

          <div className="pt-6 border-t border-slate-100">
            <button className="w-full flex items-center space-x-3 px-4 py-3 text-slate-400 hover:text-slate-600 transition-colors">
              <Settings size={20} />
              <span className="font-medium">Settings</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
          {activeTab === 'dashboard' && <Dashboard loans={loans} />}
          {activeTab === 'entry' && (
            <LoanEntryForm 
              onSave={saveLoan} 
              nextSerial={nextAutoSerial} 
              editingLoan={editingLoan} 
              onCancel={() => {
                setEditingLoan(null);
                setActiveTab('ledger');
              }}
            />
          )}
          {activeTab === 'ledger' && <Ledger loans={loans} onDelete={deleteLoan} onEdit={handleEdit} />}
          {activeTab === 'customers' && <CustomerSheet loans={loans} />}
        </div>
      </main>

      {/* Mobile Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-30 md:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie
} from 'recharts';
import { IndianRupee, Users, Scale, AlertCircle, Coins } from 'lucide-react';
import { LoanEntry } from '../types';

interface DashboardProps {
  loans: LoanEntry[];
}

const Dashboard: React.FC<DashboardProps> = ({ loans }) => {
  const stats = useMemo(() => {
    const totalPrincipal = loans.reduce((acc, curr) => acc + curr.amount, 0);
    const activeLoansCount = loans.filter(l => l.status === 'Active').length;
    const totalInterestMonthly = loans.reduce((acc, curr) => acc + (curr.amount * curr.interestRate / 100), 0);

    const metalCounts = {
      Gold: loans.filter(l => l.metalType === 'Gold').length,
      Silver: loans.filter(l => l.metalType === 'Silver').length,
      Both: loans.filter(l => l.metalType === 'Both').length,
    };

    const goldWeight = loans.reduce((acc, curr) => {
      if (curr.metalType === 'Gold') return acc + curr.weight;
      if (curr.metalType === 'Both') return acc + (curr.weight * 0.5); // Estimate split for "Both"
      return acc;
    }, 0);

    const silverWeight = loans.reduce((acc, curr) => {
      if (curr.metalType === 'Silver') return acc + curr.weight;
      if (curr.metalType === 'Both') return acc + (curr.weight * 0.5); // Estimate split for "Both"
      return acc;
    }, 0);

    return { totalPrincipal, activeLoansCount, totalInterestMonthly, metalCounts, goldWeight, silverWeight };
  }, [loans]);

  const pieData = [
    { name: 'Gold', value: stats.metalCounts.Gold, color: '#EAB308' },
    { name: 'Silver', value: stats.metalCounts.Silver, color: '#94A3B8' },
    { name: 'Both', value: stats.metalCounts.Both, color: '#FACC15' },
  ];

  const recentTrends = useMemo(() => {
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const currentYear = new Date().getFullYear();

    return months.map((month, index) => {
      const monthLoans = loans.filter(l => {
        const d = new Date(l.date);
        return d.getMonth() === index && d.getFullYear() === currentYear;
      });
      return {
        name: month,
        amount: monthLoans.reduce((sum, l) => sum + l.amount, 0)
      };
    });
  }, [loans]);

  const StatCard = ({ label, value, icon: Icon, colorClass, subValue }: any) => (
    <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-start justify-between">
      <div>
        <p className="text-slate-500 text-sm font-medium mb-1">{label}</p>
        <h3 className="text-2xl font-bold text-slate-800">{value}</h3>
        {subValue && <p className="text-xs text-slate-400 mt-1">{subValue}</p>}
      </div>
      <div className={`p-3 rounded-xl ${colorClass}`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header>
        <h1 className="text-3xl font-bold text-slate-800">Business Overview</h1>
        <p className="text-slate-500">Real-time tracking of your gold loan portfolio</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          label="Total Principal Out" 
          value={`₹${stats.totalPrincipal.toLocaleString()}`} 
          icon={IndianRupee} 
          colorClass="bg-yellow-50 text-yellow-600" 
        />
        <StatCard 
          label="Est. Monthly Interest" 
          value={`₹${stats.totalInterestMonthly.toLocaleString()}`} 
          icon={TrendingUpIcon} 
          colorClass="bg-green-50 text-green-600" 
        />
        <StatCard 
          label="Gold Stock" 
          value={`${stats.goldWeight.toFixed(2)}g`} 
          icon={Coins} 
          colorClass="bg-yellow-50 text-yellow-600" 
          subValue="Aggregate Gross Weight"
        />
        <StatCard 
          label="Silver Stock" 
          value={`${stats.silverWeight.toFixed(2)}g`} 
          icon={Scale} 
          colorClass="bg-slate-100 text-slate-600" 
          subValue="Aggregate Gross Weight"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Loan Trend Chart */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Disbursement Trend ({new Date().getFullYear()})</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={recentTrends}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="amount" fill="#EAB308" radius={[4, 4, 0, 0]} barSize={32} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Metal Distribution Chart */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
