import React, { useMemo } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie
} from 'recharts';
import { IndianRupee, Users, Scale, AlertCircle, Coins, CheckCircle } from 'lucide-react';
import { LoanEntry } from '../types';

interface DashboardProps {
  loans: LoanEntry[];
}

const Dashboard: React.FC<DashboardProps> = ({ loans }) => {
  const stats = useMemo(() => {
    const activeLoans = loans.filter(l => l.status === 'Active');
    const closedLoans = loans.filter(l => l.status === 'Closed');

    const totalPrincipal = activeLoans.reduce((acc, curr) => acc + curr.amount, 0);
    const activeLoansCount = activeLoans.length;
    const closedLoansCount = closedLoans.length;

    const totalInterestMonthly = activeLoans.reduce((acc, curr) => acc + (curr.amount * curr.interestRate / 100), 0);

    const metalCounts = {
      Gold: activeLoans.filter(l => l.metalType === 'Gold').length,
      Silver: activeLoans.filter(l => l.metalType === 'Silver').length,
      Both: activeLoans.filter(l => l.metalType === 'Both').length,
    };

    const goldWeight = activeLoans.reduce((acc, curr) => {
      if (curr.metalType === 'Gold') return acc + curr.weight;
      if (curr.metalType === 'Both') return acc + (curr.weight * 0.5);
      return acc;
    }, 0);

    const silverWeight = activeLoans.reduce((acc, curr) => {
      if (curr.metalType === 'Silver') return acc + curr.weight;
      if (curr.metalType === 'Both') return acc + (curr.weight * 0.5);
      return acc;
    }, 0);

    return { totalPrincipal, activeLoansCount, closedLoansCount, totalInterestMonthly, metalCounts, goldWeight, silverWeight };
  }, [loans]);

  const pieData = [
    { name: 'Gold', value: stats.metalCounts.Gold, color: '#EAB308' },
    { name: 'Silver', value: stats.metalCounts.Silver, color: '#94A3B8' },
    { name: 'Both', value: stats.metalCounts.Both, color: '#FACC15' },
  ];

  const recentTrends = useMemo(() => {
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const currentYear = new Date().getFullYear();

    return months.map((month, index) => {
      const monthLoans = loans.filter(l => {
        const d = new Date(l.date);
        return d.getMonth() === index && d.getFullYear() === currentYear;
      });
      return {
        name: month,
        amount: monthLoans.reduce((sum, l) => sum + l.amount, 0)
      };
    });
  }, [loans]);

  const StatCard = ({ label, value, icon: Icon, colorClass, subValue }: any) => (
    <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-start justify-between">
      <div>
