        {subValue && <p className="text-xs text-slate-400 mt-1">{subValue}</p>}
      </div>
      <div className={`p-3 rounded-xl ${colorClass}`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">Business Overview</h1>
          <p className="text-slate-500">Real-time tracking of your active gold loan portfolio</p>
        </div>
        <div className="bg-red-50 px-4 py-2 rounded-xl border border-red-100 flex items-center space-x-2">
          <CheckCircle className="text-red-500" size={20} />
          <div>
            <p className="text-xs font-bold text-red-800 uppercase leading-none">Recovered Accounts</p>
            <p className="text-lg font-bold text-red-600 leading-none mt-1">{stats.closedLoansCount}</p>
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          label="Active Principal Out" 
          value={`₹${stats.totalPrincipal.toLocaleString()}`} 
          icon={IndianRupee} 
          colorClass="bg-yellow-50 text-yellow-600" 
        />
        <StatCard 
          label="Est. Monthly Interest" 
          value={`₹${stats.totalInterestMonthly.toLocaleString()}`} 
          icon={TrendingUpIcon} 
          colorClass="bg-green-50 text-green-600" 
        />
        <StatCard 
          label="Live Gold Stock" 
          value={`${stats.goldWeight.toFixed(2)}g`} 
          icon={Coins} 
          colorClass="bg-yellow-50 text-yellow-600" 
          subValue="In Active Custody"
        />
        <StatCard 
          label="Live Silver Stock" 
          value={`${stats.silverWeight.toFixed(2)}g`} 
          icon={Scale} 
          colorClass="bg-slate-100 text-slate-600" 
          subValue="In Active Custody"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Loan Trend Chart */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Disbursement Trend ({new Date().getFullYear()})</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={recentTrends}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="amount" fill="#EAB308" radius={[4, 4, 0, 0]} barSize={32} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Metal Distribution Chart */}
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Active Asset Distribution</h3>
          <div className="h-[300px] flex items-center justify-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
