import React, { useState, useMemo } from 'react';
import { Search, Download, Filter, Trash2, Edit3, Calendar, Phone, CheckCircle2 } from 'lucide-react';
import { LoanEntry } from '../types';

interface LedgerProps {
  loans: LoanEntry[];
  onDelete: (id: string) => void;
  onEdit: (loan: LoanEntry) => void;
  onUpdateStatus: (id: string) => void;
}

const Ledger: React.FC<LedgerProps> = ({ loans, onDelete, onEdit, onUpdateStatus }) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredLoans = useMemo(() => {
    return loans.filter(loan => 
      loan.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      loan.contactNumber.includes(searchTerm) ||
      loan.serialNumber.toString().includes(searchTerm) ||
      loan.description.toLowerCase().includes(searchTerm.toLowerCase())
    ).sort((a, b) => b.serialNumber - a.serialNumber);
  }, [loans, searchTerm]);

  const calculateInterest = (amount: number, rate: number, date: string, closeDate?: string) => {
    const start = new Date(date);
    const end = closeDate ? new Date(closeDate) : new Date();
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    // Monthly interest calculation based on days (30 days = 1 month)
    const months = diffDays / 30;
    const totalMonths = Math.max(1, Math.round(months * 100) / 100); 
    return (amount * rate / 100) * totalMonths;
  };

  return (
    <div className="animate-in fade-in duration-500">
      <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">Loan Ledger</h1>
          <p className="text-slate-500">View and manage all historical loan records</p>
        </div>

        <div className="flex items-center space-x-3">
          <button className="flex items-center space-x-2 bg-white px-4 py-2 border border-slate-200 rounded-lg text-slate-600 hover:bg-slate-50 transition-colors">
            <Download size={18} />
            <span className="text-sm font-medium">Export CSV</span>
          </button>
        </div>
      </header>

      {/* Search & Filter Bar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm mb-6 flex flex-col md:flex-row gap-4">
        <div className="relative flex-grow">
          <Search className="absolute left-4 top-3 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Search by name, phone, serial or item description..."
            className="w-full pl-12 pr-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl focus:ring-2 focus:ring-yellow-500 outline-none transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <button className="flex items-center space-x-2 px-6 py-2.5 bg-slate-100 text-slate-700 rounded-xl hover:bg-slate-200 transition-colors">
          <Filter size={18} />
          <span className="font-medium">Filters</span>
        </button>
      </div>

      {/* Ledger Table */}
      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-100">
            <tr>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">S.No</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Date</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Customer</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Weight (G/N)</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Asset/Remark</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">Amount</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">Interest</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider text-center">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredLoans.map((loan) => (
              <tr key={loan.id} className={`hover:bg-slate-50/50 transition-colors group ${loan.status === 'Closed' ? 'bg-red-50/10' : ''}`}>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="font-mono text-sm font-bold text-slate-400">#{String(loan.serialNumber).padStart(4, '0')}</span>
                    {loan.status === 'Closed' && (
                      <span className="inline-flex items-center text-[10px] font-bold text-red-600 uppercase mt-1">
                        PAID
                      </span>
                    )}
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex flex-col text-slate-600">
                    <div className="flex items-center space-x-2">
                      <Calendar size={12} className="text-slate-400" />
                      <span className="text-xs">{new Date(loan.date).toLocaleDateString()}</span>
                    </div>
                    {loan.closeDate && (
                      <div className="flex items-center space-x-2 mt-1 text-red-500 font-medium">
                        <CheckCircle2 size={10} />
                        <span className="text-[10px]">{new Date(loan.closeDate).toLocaleDateString()}</span>
                      </div>
                    )}
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className={`font-bold ${loan.status === 'Closed' ? 'text-slate-500 line-through' : 'text-slate-800'}`}>{loan.name}</span>
                    <span className="text-xs text-slate-400">{loan.guardian}</span>
                    <div className="flex items-center space-x-1 mt-1">
                      <Phone size={10} className="text-slate-400" />
                      <span className="text-xs text-slate-500 font-medium">{loan.contactNumber}</span>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <div className="flex items-center space-x-1">
                      <span className="text-sm font-bold text-slate-700">{loan.weight}g</span>
                      <span className="text-xs text-slate-400">/</span>
                      <span className="text-sm font-bold text-yellow-600">{loan.netWeight || loan.weight}g</span>
                    </div>
                    <span className={`px-2 py-0.5 mt-1 rounded text-[9px] font-bold uppercase w-fit ${
                      loan.metalType === 'Gold' ? 'bg-yellow-100 text-yellow-700' :
                      loan.metalType === 'Silver' ? 'bg-slate-200 text-slate-700' :
                      'bg-orange-100 text-orange-700'
                    }`}>
                      {loan.metalType}
                    </span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex flex-col max-w-[200px]">
                    <span className="text-sm text-slate-700 font-medium truncate">{loan.description}</span>
                    <span className="text-xs text-slate-400 italic truncate">{loan.remark || 'No remark'}</span>
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <span className={`font-bold ${loan.status === 'Closed' ? 'text-slate-400' : 'text-slate-800'}`}>₹{loan.amount.toLocaleString()}</span>
                  <div className="text-[10px] text-slate-400">{loan.interestRate}% p.m.</div>
                </td>
                <td className="px-6 py-4 text-right">
                  <span className={`text-sm font-bold ${loan.status === 'Closed' ? 'text-slate-400' : 'text-green-600'}`}>
                    +₹{calculateInterest(loan.amount, loan.interestRate, loan.date, loan.closeDate).toLocaleString()}
                  </span>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center justify-center space-x-3">
                    <button 
                      onClick={() => loan.status === 'Active' ? onUpdateStatus(loan.id) : null}
                      className={`p-2 rounded-lg transition-all transform active:scale-95 ${
                        loan.status === 'Active' 
                        ? 'text-blue-500 hover:bg-blue-50 cursor-pointer' 
                        : 'text-red-600 bg-red-50 cursor-default'
                      }`}
                      title={loan.status === 'Active' ? "Mark as Paid" : "Paid Account"}
                    >
                      <CheckCircle2 size={22} />
                    </button>
                    <button 
                      onClick={() => onEdit(loan)}
                      className="p-2 text-slate-400 hover:text-yellow-600 hover:bg-yellow-50 rounded-lg transition-colors" 
                      title="Edit Entry"
                    >
                      <Edit3 size={18} />
                    </button>
                    <button 
                      onClick={() => onDelete(loan.id)}
                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors" 
                      title="Delete Record"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}

            {filteredLoans.length === 0 && (
              <tr>
                <td colSpan={8} className="px-6 py-12 text-center text-slate-500 italic">
                  {searchTerm ? "No records found matching your search." : "Your ledger is currently empty."}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Ledger;

import React, { useState, useEffect } from 'react';
import { Save, User, MapPin, Phone, Scale, Info, MessageSquare, X, CheckCircle2 } from 'lucide-react';
import { LoanEntry, MetalType } from '../types';

interface LoanEntryFormProps {
  onSave: (loan: Omit<LoanEntry, 'id' | 'status'>) => void;
  nextSerial: number;
  editingLoan: LoanEntry | null;
  onCancel?: () => void;
}

const LoanEntryForm: React.FC<LoanEntryFormProps> = ({ onSave, nextSerial, editingLoan, onCancel }) => {
  const [formData, setFormData] = useState({
    serialNumber: String(nextSerial),
    date: new Date().toISOString().split('T')[0],
    name: '',
    guardian: '',
    address: '',
    contactNumber: '',
    metalType: 'Gold' as MetalType,
    description: '',
    weight: '' as string | number,
    netWeight: '' as string | number,
    remark: '',
    amount: '' as string | number,
  });

  // Load editing data if present
  useEffect(() => {
    if (editingLoan) {
      setFormData({
        serialNumber: String(editingLoan.serialNumber),
        date: editingLoan.date,
        name: editingLoan.name,
        guardian: editingLoan.guardian,
        address: editingLoan.address,
        contactNumber: editingLoan.contactNumber,
        metalType: editingLoan.metalType,
        description: editingLoan.description,
        weight: editingLoan.weight,
        netWeight: editingLoan.netWeight,
        remark: editingLoan.remark,
        amount: editingLoan.amount,
      });
    } else {
      setFormData(prev => ({ 
        ...prev, 
        serialNumber: String(nextSerial),
        date: new Date().toISOString().split('T')[0] 
      }));
    }
  }, [editingLoan, nextSerial]);

  // Default interest rates
  const getInterestRate = (metal: MetalType) => {
    if (metal === 'Gold') return 3;
    if (metal === 'Silver') return 4;
    return 3.5;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      serialNumber: Number(formData.serialNumber),
      weight: Number(formData.weight),
      netWeight: Number(formData.netWeight),
      amount: Number(formData.amount),
      interestRate: getInterestRate(formData.metalType)
    });
  };

  const inputClass = "w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-yellow-500 focus:border-yellow-500 transition-all outline-none";
  const labelClass = "block text-sm font-semibold text-slate-700 mb-2 ml-1";

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500">
      <header className="mb-8 flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">{editingLoan ? 'Edit Loan Entry' : 'New Loan Entry'}</h1>
          <p className="text-slate-500">Record a new collateral-based loan into the ledger</p>
        </div>
        {editingLoan && (
          <button 
            onClick={onCancel}
            className="flex items-center space-x-2 text-slate-500 hover:text-slate-800 transition-colors bg-white px-4 py-2 rounded-lg border border-slate-200"
          >
            <X size={18} />
            <span>Cancel Edit</span>
          </button>
        )}
      </header>

      <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-8 space-y-8">
          {/* Header Info */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pb-6 border-b border-slate-100">
            <div>
              <label className={labelClass}>Serial Number (Auto/Manual)</label>
              <input 
                type="number"
                className={`${inputClass} font-mono font-bold`}
                value={formData.serialNumber}
                onChange={e => setFormData({...formData, serialNumber: e.target.value})}
                required
              />
            </div>
            <div>
              <label className={labelClass}>Entry Date</label>
              <input 
                type="date" 
                className={inputClass}
                value={formData.date}
                onChange={e => setFormData({...formData, date: e.target.value})}
                required
              />
            </div>
          </div>

          {/* Customer Section */}
          <div className="space-y-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center space-x-2">
              <User size={20} className="text-yellow-500" />
              <span>Customer Information</span>
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelClass}>Customer Full Name</label>
                <input 
                  type="text" 
                  className={inputClass}
                  placeholder="e.g. Rahul Sharma"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  required
                />
              </div>
              <div>
                <label className={labelClass}>Guardian/Father's Name</label>
                <input 
                  type="text" 
                  className={inputClass}
                  placeholder="e.g. S/o Mr. Vijay Sharma"
                  value={formData.guardian}
                  onChange={e => setFormData({...formData, guardian: e.target.value})}
                  required
                />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelClass}>Contact Number</label>
