                  )}
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center justify-center space-x-2">
                    {/* Primary Settlement Tick Mark */}
                    <button 
                      onClick={() => loan.status === 'Active' ? onUpdateStatus(loan.id) : null}
