          </div>

          {/* Date of Closure - VERY END OF FORM FIELDS */}
          {editingLoan && formData.status === 'Closed' && (
            <div className="pt-8 border-t-2 border-dashed border-red-100 animate-in fade-in slide-in-from-top-2">
              <div className="bg-red-600 rounded-2xl p-6 text-white shadow-xl flex items-center justify-between">
                <div className="flex items-center space-x-4">
                  <div className="bg-white/20 p-3 rounded-full">
                    <CheckCircle2 size={32} />
