                </div>
              </div>
            </div>
          )}
        </div>

        <div className="bg-slate-50 p-6 flex justify-end">
          <button type="submit" className="bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-3 px-10 rounded-xl shadow-lg shadow-yellow-200 transition-all flex items-center space-x-2">
            <Save size={20} />
            <span>{editingLoan ? 'Save Changes' : 'Submit Entry'}</span>
          </button>
        </div>
      </form>
    </div>
  );
};

