import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  PlusCircle, 
  BookOpen, 
  TrendingUp,
  Settings,
  Menu,
  X,
  Users
} from 'lucide-react';
import { LoanEntry } from './types';
import Dashboard from './components/Dashboard';
import LoanEntryForm from './components/LoanEntryForm';
import Ledger from './components/Ledger';
import CustomerSheet from './components/CustomerSheet';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'entry' | 'ledger' | 'customers'>('dashboard');
  const [loans, setLoans] = useState<LoanEntry[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [editingLoan, setEditingLoan] = useState<LoanEntry | null>(null);

  // Load data from LocalStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('girvi_loans');
    if (saved) {
      try {
        setLoans(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved loans", e);
      }
    }
  }, []);

  // Save data to LocalStorage on change
  useEffect(() => {
    localStorage.setItem('girvi_loans', JSON.stringify(loans));
  }, [loans]);

  const saveLoan = (loanData: Omit<LoanEntry, 'id'>) => {
    if (editingLoan) {
      let closeDate = editingLoan.closeDate;
      if (loanData.status === 'Closed' && !closeDate) {
        closeDate = new Date().toISOString().split('T')[0];
      } else if (loanData.status === 'Active') {
        closeDate = undefined;
      }

      setLoans(loans.map(l => l.id === editingLoan.id ? { ...loanData, id: editingLoan.id, closeDate } : l));
      setEditingLoan(null);
    } else {
      const loan: LoanEntry = {
        ...loanData,
        id: crypto.randomUUID(),
        closeDate: loanData.status === 'Closed' ? new Date().toISOString().split('T')[0] : undefined
      };
      setLoans([...loans, loan]);
    }
    setActiveTab('ledger');
  };

  const deleteLoan = (id: string) => {
    if (window.confirm("Are you sure you want to delete this record?")) {
      setLoans(loans.filter(l => l.id !== id));
    }
  };

  const closeLoan = (id: string) => {
    const loan = loans.find(l => l.id === id);
    if (!loan) return;

    if (loan.status === 'Closed') {
      if (window.confirm("Re-open this loan account as UNPAID?")) {
        setLoans(loans.map(l => l.id === id ? { ...l, status: 'Active', closeDate: undefined } : l));
      }
    } else {
      const date = new Date().toISOString().split('T')[0];
      if (window.confirm(`Mark this loan as PAID? (Settlement Date: ${date})`)) {
        setLoans(loans.map(l => l.id === id ? { ...l, status: 'Closed', closeDate: date } : l));
      }
    }
  };

  const handleEdit = (loan: LoanEntry) => {
    setEditingLoan(loan);
    setActiveTab('entry');
  };

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const NavItem = ({ id, icon: Icon, label }: { id: typeof activeTab, icon: any, label: string }) => (
    <button
      onClick={() => {
        setActiveTab(id);
        if (id !== 'entry') setEditingLoan(null);
        setIsSidebarOpen(false);
      }}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
        activeTab === id 
          ? 'bg-yellow-500 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-yellow-50 hover:text-yellow-600'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium">{label}</span>
    </button>
  );

  const nextAutoSerial = loans.length > 0 ? Math.max(...loans.map(l => l.serialNumber)) + 1 : 1;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Mobile Header */}
      <div className="md:hidden bg-white border-b border-slate-200 px-4 py-3 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center space-x-2">
          <div className="bg-yellow-500 p-2 rounded-lg text-white">
            <TrendingUp size={24} />
          </div>
          <span className="text-xl font-bold text-slate-800">GirviGold</span>
        </div>
        <button onClick={toggleSidebar} className="text-slate-600">
          {isSidebarOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-40 w-64 bg-white border-r border-slate-200 transform transition-transform duration-200 ease-in-out md:relative md:translate-x-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-6">
          <div className="hidden md:flex items-center space-x-3 mb-10 px-2">
            <div className="bg-yellow-500 p-2 rounded-xl text-white shadow-md">
              <TrendingUp size={24} />
            </div>
            <span className="text-2xl font-bold text-slate-800 tracking-tight">GirviGold</span>
          </div>

          <nav className="space-y-2 flex-grow">
            <NavItem id="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem id="entry" icon={PlusCircle} label={editingLoan ? "Edit Loan Entry" : "New Loan Entry"} />
            <NavItem id="ledger" icon={BookOpen} label="Loan Ledger" />
            <NavItem id="customers" icon={Users} label="Customer Sheet" />
          </nav>

          <div className="pt-6 border-t border-slate-100">
            <button className="w-full flex items-center space-x-3 px-4 py-3 text-slate-400 hover:text-slate-600 transition-colors">
              <Settings size={20} />
              <span className="font-medium">Settings</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
          {activeTab === 'dashboard' && <Dashboard loans={loans} />}
          {activeTab === 'entry' && (
            <LoanEntryForm 
              onSave={saveLoan} 
              nextSerial={nextAutoSerial} 
              editingLoan={editingLoan} 
              onCancel={() => {
                setEditingLoan(null);
                setActiveTab('ledger');
              }}
            />
          )}
          {activeTab === 'ledger' && <Ledger loans={loans} onDelete={deleteLoan} onEdit={handleEdit} onUpdateStatus={closeLoan} />}
          {activeTab === 'customers' && <CustomerSheet loans={loans} />}
        </div>
      </main>

      {/* Mobile Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-30 md:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Search, Download, Filter, Trash2, Edit3, Calendar, Phone, CheckCircle2 } from 'lucide-react';
import { LoanEntry } from '../types';

interface LedgerProps {
  loans: LoanEntry[];
  onDelete: (id: string) => void;
  onEdit: (loan: LoanEntry) => void;
  onUpdateStatus: (id: string) => void;
}

const Ledger: React.FC<LedgerProps> = ({ loans, onDelete, onEdit, onUpdateStatus }) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredLoans = useMemo(() => {
    return loans.filter(loan => 
      loan.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      loan.contactNumber.includes(searchTerm) ||
      loan.serialNumber.toString().includes(searchTerm) ||
      loan.description.toLowerCase().includes(searchTerm.toLowerCase())
    ).sort((a, b) => b.serialNumber - a.serialNumber);
  }, [loans, searchTerm]);

  const calculateInterest = (amount: number, rate: number, date: string, closeDate?: string) => {
    const start = new Date(date);
    const end = closeDate ? new Date(closeDate) : new Date();
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    // Interest calculation: Treat 30 days as 1 month. Minimum 1 month interest.
    const months = diffDays / 30;
    const totalMonths = Math.max(1, Math.round(months * 100) / 100); 
    return (amount * rate / 100) * totalMonths;
  };

  return (
    <div className="animate-in fade-in duration-500">
      <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">Loan Ledger</h1>
          <p className="text-slate-500">Real-time status of all collateral records</p>
        </div>

        <div className="flex items-center space-x-3">
          <button className="flex items-center space-x-2 bg-white px-4 py-2 border border-slate-200 rounded-lg text-slate-600 hover:bg-slate-50 transition-colors">
            <Download size={18} />
            <span className="text-sm font-medium">Export Data</span>
          </button>
        </div>
      </header>

      {/* Search Bar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm mb-6 flex flex-col md:flex-row gap-4">
        <div className="relative flex-grow">
          <Search className="absolute left-4 top-3 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Search by name, phone, or serial..."
            className="w-full pl-12 pr-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl focus:ring-2 focus:ring-yellow-500 outline-none transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <button className="flex items-center space-x-2 px-6 py-2.5 bg-slate-100 text-slate-700 rounded-xl hover:bg-slate-200 transition-colors">
          <Filter size={18} />
          <span className="font-medium">Filter</span>
        </button>
      </div>

      {/* Ledger Table */}
      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-100">
            <tr>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">S.No</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Customer Info</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Item Details</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">Principal</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">Interest</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider text-center">Settlement</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredLoans.map((loan) => (
              <tr key={loan.id} className={`hover:bg-slate-50/50 transition-colors group ${loan.status === 'Closed' ? 'bg-red-50/10' : ''}`}>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="font-mono text-sm font-bold text-slate-500">#{String(loan.serialNumber).padStart(4, '0')}</span>
                    {loan.status === 'Closed' && (
                      <span className="text-[10px] font-black text-red-600 uppercase mt-1">PAID</span>
                    )}
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className={`font-bold ${loan.status === 'Closed' ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{loan.name}</span>
                    <div className="flex items-center space-x-1 mt-1">
                      <Phone size={10} className="text-slate-400" />
                      <span className="text-xs text-slate-500">{loan.contactNumber}</span>
                    </div>
                    <div className="flex items-center space-x-1 mt-0.5 text-slate-400">
                      <Calendar size={10} />
                      <span className="text-[10px] uppercase font-bold">In: {new Date(loan.date).toLocaleDateString()}</span>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <div className="flex items-center space-x-1">
                      <span className="text-sm font-bold text-slate-700">{loan.netWeight || loan.weight}g</span>
                      <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase ${
                        loan.metalType === 'Gold' ? 'bg-yellow-100 text-yellow-700' : 'bg-slate-200 text-slate-700'
                      }`}>
                        {loan.metalType}
                      </span>
                    </div>
                    <span className="text-xs text-slate-500 truncate max-w-[150px]">{loan.description}</span>
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <span className={`font-bold ${loan.status === 'Closed' ? 'text-slate-400' : 'text-slate-800'}`}>₹{loan.amount.toLocaleString()}</span>
                  <div className="text-[10px] text-slate-400">{loan.interestRate}% p.m.</div>
                </td>
                <td className="px-6 py-4 text-right">
                  <span className={`text-sm font-bold ${loan.status === 'Closed' ? 'text-slate-400' : 'text-green-600'}`}>
                    +₹{calculateInterest(loan.amount, loan.interestRate, loan.date, loan.closeDate).toLocaleString()}
                  </span>
                  {loan.closeDate && (
                    <div className="text-[9px] font-bold text-red-500 uppercase">Halted on {new Date(loan.closeDate).toLocaleDateString()}</div>
                  )}
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center justify-center space-x-2">
                    {/* Settlement Tick Mark */}
                    <button 
                      onClick={() => onUpdateStatus(loan.id)}
                      className={`p-2 rounded-full transition-all transform active:scale-90 shadow-sm border ${
                        loan.status === 'Active' 
                        ? 'text-blue-500 bg-blue-50 hover:bg-blue-100 border-blue-200' 
                        : 'text-red-600 bg-red-100 hover:bg-red-200 border-red-200'
                      }`}
                      title={loan.status === 'Active' ? "Click to Mark as PAID" : "Click to Re-open as UNPAID"}
                    >
                      <CheckCircle2 size={24} />
                    </button>

                    {/* Other actions visible on hover */}
                    <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => onEdit(loan)} className="p-1.5 text-slate-400 hover:text-yellow-600 hover:bg-yellow-50 rounded-lg">
                        <Edit3 size={16} />
                      </button>
                      <button onClick={() => onDelete(loan.id)} className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg">
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                </td>
              </tr>
            ))}
            {filteredLoans.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-12 text-center text-slate-400 italic">No matching records found.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Ledger;

